import {AIRWAY_KIT,airwayStageText,OR_CONTROL_EXTENSION} from './airway-case.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,value='',disabled=false)=>`<button class="primary-button" data-airway-action="${action}" data-airway-value="${value}" ${disabled?'disabled':''}>${text}</button>`;
function gearArt(t){return`<svg class="airway-art" viewBox="0 0 520 175" role="img" aria-label="portable fiber攜帶盒與工作帶"><rect x="25" y="30" width="205" height="120" rx="14" fill="#425b65" stroke="#96aaa6" stroke-width="3"/><rect x="48" y="49" width="75" height="50" rx="8" fill="#233a44"/><circle cx="85" cy="75" r="15" fill="#a6c5bd"/><path d="M143 58q65-20 65 35t-58 23" fill="none" stroke="#c1cebe" stroke-width="8"/><text x="125" y="138" fill="#f3e7ce" text-anchor="middle" font-size="16">PORTABLE FIBER ${t.kit.includes('fiber')?'✓':''}</text><path d="M275 45h210v93H275Z" fill="#6a6659" stroke="#a8b1a2" stroke-width="3"/><path d="M296 54v62m39-62v62m39-62v62m39-62v62m39-62v62" stroke="#c5bc9f" stroke-width="9"/><path d="M280 48v88h200V48" fill="none" stroke="#384b51" stroke-width="13"/><text x="380" y="161" fill="#405d60" text-anchor="middle" font-size="18">工作帶 ${t.kit.includes('belt')?'✓':''}</text></svg>`;}
function teamArt(t){return`<div class="airway-team-scene" role="img" aria-label="急診、麻醉科與二線共同處理的簡化示意"><span>急診</span><span>麻醉科</span><span>二線學長</span><div class="airway-bed">${t.stage==='ventilator'?'VENTILATOR':'TEAM / STAND BY'}<i></i></div></div>`;}
export function airwayHTML(t,message=''){
 let body='';const stage=t.stage;
 if(stage==='phone')body='<div class="dialogue">急診：「有一位tumor bleeding的病人，麻醉科插管插不上，請你們來急診stand by！」</div>'+btn('先通知二線，帶齊裝備去急診','notify');
 if(stage==='gear')body=gearArt(t)+'<p class="modal-copy">二線已通知。出發前確認隨身裝備，不另繞回診間。</p>'+AIRWAY_KIT.map(k=>btn((t.kit.includes(k.id)?'✓ ':'')+k.name,'kit',k.id,t.kit.includes(k.id))).join('')+btn('帶齊裝備，衝去1F急診','depart','',t.kit.length!==2);
 if(stage==='arrival')body=teamArt(t)+'<div class="dialogue">麻醉科：「目前還是無法on上endo。」<br>二線：「先確認現況，準備急氣切。」</div>'+btn('到場確認麻醉科仍無法插管，接上二線','confirm-failed');
 if(stage==='prepare')body=teamArt(t)+['team','equipment'].map((id,i)=>btn((t.prepared.includes(id)?'✓ ':'')+['與二線、麻醉科確認現場分工','確認工作帶與現場器材準備'][i],'prepare',id,t.prepared.includes(id))).join('')+btn('準備完成，與二線一起處理','ready','',t.prepared.length!==2);
 if(stage==='procedure')body=teamArt(t)+'<p class="modal-copy">依畫面順序配合團隊，完成這段簡化操作。</p><div class="airway-assist">'+['準備就位','配合二線操作','完成急氣切'].map((text,i)=>btn((i<t.procedure.length?'✓ ':'')+text,'assist',i,i!==t.procedure.length)).join('')+'</div>';
 if(stage==='ventilator')body=teamArt(t)+btn(t.ventilator.includes('connect')?'✓ 已接上ventilator':'接上ventilator','ventilator','connect',t.ventilator.includes('connect'))+btn(t.ventilator.includes('confirm')?'✓ 已與麻醉科確認':'與麻醉科確認通氣及監測沒有問題','ventilator','confirm',!t.ventilator.includes('connect')||t.ventilator.includes('confirm'))+btn('確認穩定，去電腦輸刀','stable','',t.ventilator.length!==2);
 if(stage==='booking')body=`<div class="work-terminal-bar"><span>ENT / URGENT OR REQUEST</span><b>急診工作站</b></div><div class="npx-paper"><strong>${esc(t.patient.name)}</strong><span>病歷號 ${t.patient.id} · revise tracheostomy · 16房</span></div><div class="airway-order"><label>病人<select data-airway-field="patient"><option value="">請選擇</option><option value="${t.patient.id}" ${t.draft.patient===t.patient.id?'selected':''}>${t.patient.name} · ${t.patient.id}</option><option value="wrong">另一位病人</option></select></label><label>手術<select data-airway-field="procedure"><option value="">請選擇</option><option value="revise-tracheostomy" ${t.draft.procedure==='revise-tracheostomy'?'selected':''}>Revise tracheostomy</option><option value="npx">NPX biopsy</option></select></label><label>房號<select data-airway-field="room"><option value="">請選擇</option>${[13,16].map(n=>`<option value="${n}" ${t.draft.room===String(n)?'selected':''}>${n}房</option>`).join('')}</select></label></div>`+btn('核對資料，送出輸刀','book');
 if(stage==='dial')body='<div class="dialogue">先輸刀，再打電話給控台確認接刀安排。</div>'+btn('看院內電話單','directory')+(t.directoryRead?`<div class="airway-directory">公務課 3000　聽力室 2181<br>7F 3363　SICU 3462<br><b>刀房控台 ${OR_CONTROL_EXTENSION}</b></div>`:'')+`<output class="airway-digits" aria-label="目前撥號">${t.digits||'— — — — —'}</output><div class="airway-keypad">${['1','2','3','4','5','6','7','8','9','清除','0'].map(k=>btn(k,k==='清除'?'clear':'digit',k)).join('')}</div>`+btn('撥給刀房控台','call');
 if(stage==='waiting')body='<div class="dialogue">控台：「收到，等可以接刀再打給你。」</div><p class="modal-copy">病人由現場團隊持續照護。等控台回電，原本其他待辦仍可切換。</p><p class="airway-wait" role="status">等待控台通知接刀……</p>';
 if(stage==='control-called')body='<div class="dialogue">控台正在回電。</div><button id="airwayAnswerControl" class="primary-button">接聽控台回電</button>';
 if(stage==='transfer')body='<div class="dialogue">控台已通知16房接刀，二線與你一起到場。</div>'+btn('與二線進16房，核對revise工作','arrive-or');
 if(stage==='revise')body='<div class="dialogue">二線：「來，一起把這台revise收好。」</div>'+btn('跟二線開始16房revise','start-revise');
 return`<span class="modal-tag urgent">急診支援 · 腫瘤出血／插管困難</span><h2 id="modalTitle">${airwayStageText(t)}</h2><p class="fish-patient"><b>${esc(t.patient.name)}</b><span>病歷號 ${t.patient.id}</span></p>${body}<p id="airwayFeedback" class="activity-feedback" role="status">${esc(message)}</p><p class="small-note">科內娛樂的簡化情境</p><button id="airwayLater" class="secondary-button">先離開畫面，進度保留</button>`;
}
export function bindAirway({act,later,answer}){document.querySelectorAll('[data-airway-action]').forEach(b=>b.onclick=()=>act(b.dataset.airwayAction,b.dataset.airwayAction==='assist'?Number(b.dataset.airwayValue):b.dataset.airwayValue));document.querySelectorAll('[data-airway-field]').forEach(el=>el.onchange=()=>act('edit',{field:el.dataset.airwayField,value:el.value}));document.getElementById('airwayLater').onclick=later;const button=document.getElementById('airwayAnswerControl');if(button)button.onclick=answer;}
